/* ── Query parsing ───────────────────────────────────────────────────────── */

/* Parse a decimal "<key>=<n>" param out of a CoAP URI-Query string. */
static int64_t q_int(const coap_string_t *q, const char *key, int64_t def)
{
    if (!q || !q->s) return def;
    const char *s = (const char *)q->s;
    size_t klen = strlen(key);
    for (const char *p = strstr(s, key); p; p = strstr(p + 1, key)) {
        if ((p == s || p[-1] == '&') && p[klen] == '=')
            return strtoll(p + klen + 1, NULL, 10);
    }
    return def;
}

/* ── Worker + handler (CoAP separate response) ───────────────────────────── */

typedef struct {
    coap_session_t *session;
    uint8_t         token[8];
    size_t          token_len;
    int64_t         from, to;
    int             bucket;
    bool            want_series;   /* false → skip per-device breakdown (series=0) */
} energy_job_t;

/* Single persistent worker fed by a queue. Created once with a PSRAM stack
 * (xTaskCreateWithCaps) so it costs ~zero scarce internal RAM — the old
 * per-request xTaskCreate needed an 8 KB *internal* stack, which failed with
 * "5.00 Internal Server Error" once subscriptions drove internal free down to
 * ~12 KB. It never self-deletes, avoiding the vTaskDeleteWithCaps self-delete
 * path (which spawns an internal cleanup task and abort()s if that fails). */
#define ENERGY_Q_DEPTH 4
static QueueHandle_t s_energy_q = NULL;

static void energy_process(energy_job_t *job)
{
    uint8_t *buf = NULL;
    size_t   len = 0;
    flux_EnergyHistory *hist = (flux_EnergyHistory *)calloc(1, sizeof(*hist));
    if (hist) {
        aggregate(job->from, job->to, job->bucket, job->want_series, hist);
        buf = (uint8_t *)malloc(flux_EnergyHistory_size);
        if (buf) {
            pb_ostream_t os = pb_ostream_from_buffer(buf, flux_EnergyHistory_size);
            if (pb_encode(&os, flux_EnergyHistory_fields, hist)) {
                len = os.bytes_written;
            } else {
                ESP_LOGE(TAG, "pb_encode failed: %s", PB_GET_ERROR(&os));
                free(buf);
                buf = NULL;
            }
        }
        free(hist);
    }

    notify_t *n = (notify_t *)malloc(sizeof(notify_t));
    if (n) {
        memset(n, 0, sizeof(*n));
        n->type           = NOTIFY_TYPE_ENERGY_HISTORY;
        n->md_session     = job->session;
        n->md_token_len   = job->token_len;
        memcpy(n->md_token, job->token, job->token_len);
        n->md_payload     = buf;     /* NULL → reply empty */
        n->md_payload_len = len;
        if (xQueueSend(flux_coap_notify_queue, &n, pdMS_TO_TICKS(1000)) != pdTRUE) {
            free(n);
            free(buf);
            coap_session_release(job->session);
        }
    } else {
        free(buf);
        coap_session_release(job->session);
    }
    free(job);
}

static void energy_worker(void *arg)
{
    (void)arg;
    for (;;) {
        energy_job_t *job = NULL;
        if (xQueueReceive(s_energy_q, &job, portMAX_DELAY) == pdTRUE && job)
            energy_process(job);
    }
}

/* Lazily create the queue + persistent PSRAM-stack worker on first use. Safe
 * without locking: all CoAP handlers run on the single coap_server task. */
static bool energy_worker_ready(void)
{
    if (s_energy_q) return true;
    s_energy_q = xQueueCreate(ENERGY_Q_DEPTH, sizeof(energy_job_t *));
    if (!s_energy_q) return false;
    if (xTaskCreateWithCaps(energy_worker, "energy_hist", 8192, NULL, 4, NULL,
                            MALLOC_CAP_SPIRAM) != pdPASS) {
        vQueueDelete(s_energy_q);
        s_energy_q = NULL;
        return false;
    }

