/* ── Streaming per-device counter-difference state ───────────────────────── */

typedef struct {
    uint64_t node_id;
    int      cls;
    int      cur_bucket;            /* bucket currently accumulating; -1 = unseen */
    int      series_idx;            /* index into out->device_series, or -1 (PV only) */
    bool     have_import, have_export;
    int64_t  base_import, base_export;   /* counter at end of last closed bucket */
    int64_t  last_import, last_export;   /* latest counter within current bucket */
} dev_state_t;

/* Route a per-bucket counter delta (mWh) into the right proto fields (Wh). */
static void route(flux_EnergyBucket *bk, int cls, int64_t imp_mwh, int64_t exp_mwh)
{
    if (imp_mwh < 0) imp_mwh = 0;   /* guard counter resets / reboots */
    if (exp_mwh < 0) exp_mwh = 0;
    switch (cls) {
        case CLS_GRID:
            bk->grid_import_wh += (uint32_t)(imp_mwh / 1000);
            bk->grid_export_wh += (uint32_t)(exp_mwh / 1000);
            break;
        case CLS_PV:
            /* Generation lands on different counters by device: a SunSpec
             * inverter reports it as export (2.8.0), a smart plug metering a
             * balcony PV reports it as import (1.8.0). Sum both — the unused
             * counter is ~0 for each — so either convention is captured. */
            bk->pv_wh += (uint32_t)((imp_mwh + exp_mwh) / 1000);
            break;
        case CLS_LOAD:
            bk->load_wh += (uint32_t)(imp_mwh / 1000);
            break;
        case CLS_BATTERY:
            bk->battery_charge_wh    += (uint32_t)(imp_mwh / 1000);  /* into battery */
            bk->battery_discharge_wh += (uint32_t)(exp_mwh / 1000);  /* out of battery */
            break;
        default: break;
    }
}

static void close_bucket(dev_state_t *d, flux_EnergyHistory *out)
{
    if (d->cur_bucket < 0 || d->cur_bucket >= (int)out->buckets_count) return;
    int64_t imp = d->have_import ? d->last_import - d->base_import : 0;
    int64_t exp = d->have_export ? d->last_export - d->base_export : 0;
    route(&out->buckets[d->cur_bucket], d->cls, imp, exp);
    /* Per-device PV breakdown: mirror this device's generation into its own
     * series (import + export, matching route() — plug vs inverter counter). */
    if (d->cls == CLS_PV && d->series_idx >= 0) {
        int64_t i = imp < 0 ? 0 : imp;
        int64_t e = exp < 0 ? 0 : exp;
        out->device_series[d->series_idx].wh[d->cur_bucket] += (uint32_t)((i + e) / 1000);
    }
    d->base_import = d->last_import;
    d->base_export = d->last_export;
}

static dev_state_t *dev_get(dev_state_t *devs, int *n, uint64_t node_id, int cls)
{
    for (int i = 0; i < *n; i++)
        if (devs[i].node_id == node_id) return &devs[i];
    if (*n >= ENERGY_MAX_DEVS) return NULL;
    dev_state_t *d = &devs[(*n)++];
    memset(d, 0, sizeof(*d));
    d->node_id = node_id;
    d->cls = cls;
    d->cur_bucket = -1;
    d->series_idx = -1;
    return d;
}

static void process_row(dev_state_t *devs, int *n_devs, flux_EnergyHistory *out,
                        bool want_series,
                        uint64_t node_id, int cls, const char *name, int b,
                        bool has_imp, int64_t imp, bool has_exp, int64_t exp)
{
    dev_state_t *d = dev_get(devs, n_devs, node_id, cls);
    if (!d) return;

    /* A device can be reclassified mid-window (the app changes its energy role,
     * e.g. a plug retagged from load to PV); route by the latest class, not the
     * first-seen one, so the change takes effect within the window. */
    d->cls = cls;

    /* Break PV out per inverter (bounded); allocated the first time the device
     * is seen as PV. The summed buckets are unchanged. */
    if (want_series && cls == CLS_PV && d->series_idx < 0 &&
        out->device_series_count < ENERGY_MAX_SERIES) {
        int k = out->device_series_count++;
        flux_EnergyDeviceSeries *s = &out->device_series[k];
        s->node_id  = node_id;
        s->cls      = flux_EnergyClass_ENERGY_CLASS_PV;
        strlcpy(s->name, name ? name : "", sizeof(s->name));
        s->wh_count = out->buckets_count;  /* dense; wh[] zeroed by calloc */
        d->series_idx = k;
    }

    if (d->cur_bucket < 0) {                 /* first row for this device */
        d->cur_bucket = b;
        if (has_imp) { d->have_import = true; d->base_import = imp; d->last_import = imp; }
        if (has_exp) { d->have_export = true; d->base_export = exp; d->last_export = exp; }
        return;
    }
    if (b > d->cur_bucket) {                  /* advanced past the current bucket */
        const bool gap = (b - d->cur_bucket) > 1;
        close_bucket(d, out);                 /* flush energy accrued in the old bucket */
        d->cur_bucket = b;
        if (gap) {
            /* A whole bucket had no rows — with 10 s sampling that's a real
             * outage (e.g. a controller reboot), not normal jitter. Rebase the
             * baseline to this reading so the counter growth accumulated during
             * the gap isn't dumped into a single bucket as a huge false spike.
             * The (genuinely unknown) energy during the gap is dropped. */
            if (has_imp) { d->base_import = imp; d->last_import = imp; }
            if (has_exp) { d->base_export = exp; d->last_export = exp; }
        }
    }
    if (has_imp) { if (!d->have_import) { d->have_import = true; d->base_import = imp; } d->last_import = imp; }
    if (has_exp) { if (!d->have_export) { d->have_export = true; d->base_export = exp; } d->last_export = exp; }
}

/* Split a CSV line in place. Returns the field count; cols[] point into line. */
static int split_csv(char *line, char *cols[], int max)
{
    size_t L = strlen(line);
    while (L && (line[L - 1] == '\n' || line[L - 1] == '\r')) line[--L] = '\0';
    int n = 0;
    cols[n++] = line;
    for (char *p = line; *p && n < max; p++) {
        if (*p == ',') { *p = '\0'; cols[n++] = p + 1; }
    }
    return n;
}

/* ── Aggregation ─────────────────────────────────────────────────────────── */

static void aggregate(int64_t from, int64_t to, int bucket_sec, bool want_series,
                      flux_EnergyHistory *out)
{
    if (bucket_sec < ENERGY_MIN_BUCKET_SEC) bucket_sec = ENERGY_DEFAULT_BUCKET_SEC;
    if (to <= from) to = from + bucket_sec;

    int64_t start = (from / bucket_sec) * bucket_sec;   /* align down */
    int64_t span  = to - start;
    int n_buckets = (int)((span + bucket_sec - 1) / bucket_sec);
    if (n_buckets < 1) n_buckets = 1;
    if (n_buckets > ENERGY_MAX_BUCKETS) { n_buckets = ENERGY_MAX_BUCKETS; out->truncated = true; }
    int64_t eff_to = start + (int64_t)n_buckets * bucket_sec;

    out->start          = start;
    out->bucket_seconds = (uint32_t)bucket_sec;
    out->from           = from;
    out->to             = to;
    out->buckets_count  = (pb_size_t)n_buckets;
    for (int i = 0; i < n_buckets; i++) {
        memset(&out->buckets[i], 0, sizeof(out->buckets[i]));
        out->buckets[i].index = (uint32_t)i;
    }

    static dev_state_t devs[ENERGY_MAX_DEVS];   /* worker task is single-threaded */
    int  n_devs = 0;
    bool any_unsynced = false;
    int  files = 0, rows = 0;

    for (int64_t d = (start / 86400) * 86400; d < eff_to; d += 86400) {
        char date[9];
        struct tm tm;
        time_t dd = (time_t)d;
        gmtime_r(&dd, &tm);
        strftime(date, sizeof(date), "%Y%m%d", &tm);
        char path[64];
        snprintf(path, sizeof(path), FLUX_ENERGY_DIR "/%s.csv", date);

        FILE *f = fopen(path, "r");
        if (!f) continue;
        files++;

        char line[256];
        char *cols[FLUX_ELOG_COL_COUNT + 2];
        while (fgets(line, sizeof(line), f)) {
            if (line[0] == '#') continue;
            int nc = split_csv(line, cols, FLUX_ELOG_COL_COUNT + 2);
            if (nc < FLUX_ELOG_COL_COUNT) continue;                 /* short/garbled */
            if (strcmp(cols[FLUX_ELOG_COL_TIMESTAMP], "timestamp") == 0) continue; /* header */

            int64_t ts = iso_to_epoch(cols[FLUX_ELOG_COL_TIMESTAMP]);
            if (ts < start || ts >= eff_to) continue;
            int cls = class_of(cols[FLUX_ELOG_COL_DEVICE_CLASS]);
            if (cls == CLS_NONE) continue;

            int b = (int)((ts - start) / bucket_sec);
            if (b < 0 || b >= n_buckets) continue;

            uint64_t node_id = strtoull(cols[FLUX_ELOG_COL_NODE_ID], NULL, 16);
            if (cols[FLUX_ELOG_COL_TIME_SYNCED][0] != '1') any_unsynced = true;

            const char *si = cols[FLUX_ELOG_COL_ENERGY_IMPORT_MWH];
            const char *se = cols[FLUX_ELOG_COL_ENERGY_EXPORT_MWH];
            bool has_imp = si[0] != '\0';
            bool has_exp = se[0] != '\0';
            int64_t imp = has_imp ? strtoll(si, NULL, 10) : 0;
            int64_t exp = has_exp ? strtoll(se, NULL, 10) : 0;

            process_row(devs, &n_devs, out, want_series, node_id, cls,
                        cols[FLUX_ELOG_COL_DEVICE_NAME], b, has_imp, imp, has_exp, exp);
            rows++;
        }
        fclose(f);
    }

    for (int i = 0; i < n_devs; i++) close_bucket(&devs[i], out);   /* flush finals */
    out->time_synced = !any_unsynced;

    ESP_LOGI(TAG, "history: %d bucket(s) @%ds from %d file(s), %d row(s), %d dev(s)%s",
             n_buckets, bucket_sec, files, rows, n_devs,
             out->truncated ? " [truncated]" : "");

