import 'package:flutter/foundation.dart';
import 'package:matter_home/services/proto/flux.pb.dart' as $proto;

/// One time bucket of the energy-history chart, expressed as **average power in
/// watts** over the bucket (so lines read as instantaneous-ish power, kW).
///
/// The controller reports watt-hours accumulated per bucket; average power is
/// `Wh / (bucketSeconds / 3600)`.
@immutable
class EnergyHistoryPoint {
  const EnergyHistoryPoint({
    required this.time,
    required this.pvW,
    required this.gridImportW,
    required this.gridExportW,
    required this.loadW,
  });

  final DateTime time;
  final double pvW;         // PV generation
  final double gridImportW; // drawn from the grid
  final double gridExportW; // fed to the grid
  final double loadW;       // home consumption

  double get maxSeries =>
      [pvW, gridImportW, gridExportW, loadW].reduce((a, b) => a > b ? a : b);

  /// Whole-home consumption for this bucket (average W), from the energy
  /// balance: generation + import − export. Clamped ≥ 0. (Battery isn't in the
  /// per-bucket series, so it's omitted here — fine for the price overlay.)
  double get consumptionW {
    final c = pvW + gridImportW - gridExportW;
    return c > 0 ? c : 0;
  }
}

/// One PV inverter's generation over the same time base — average power (W) per
/// bucket, index-aligned to [EnergyHistoryData.points].
@immutable
class PvDeviceSeries {
  const PvDeviceSeries({
    required this.nodeId,
    required this.name,
    required this.wattsPerBucket,
    required this.kwh,
  });

  final int nodeId;
  final String name;
  final List<double> wattsPerBucket;
  final double kwh; // window total

  double get peakW =>
      wattsPerBucket.isEmpty ? 0 : wattsPerBucket.reduce((a, b) => a > b ? a : b);
}

/// A decoded, chart-ready energy history: the per-bucket power series plus the
/// window totals (kWh) and derived KPIs. Built from the controller's
/// [$proto.EnergyHistory]; the UI never sees raw protobuf.
@immutable
class EnergyHistoryData {
  const EnergyHistoryData({
    required this.points,
    required this.bucket,
    required this.timeSynced,
    required this.truncated,
    required this.pvKwh,
    required this.gridImportKwh,
    required this.gridExportKwh,
    required this.loadKwh,
    this.batteryChargeKwh = 0,
    this.batteryDischargeKwh = 0,
    this.pvSeries = const [],
  });

  final List<EnergyHistoryPoint> points;
  final Duration bucket;
  final bool timeSynced; // false → times approximate (pre-SNTP rows)
  final bool truncated;  // true → range exceeded the per-response cap

  final double pvKwh;
  final double gridImportKwh;
  final double gridExportKwh;
  /// Sum of load-classed devices' consumption (monitored appliances only — not
  /// necessarily whole-home; prefer [consumptionKwh] for totals).
  final double loadKwh;
  final double batteryChargeKwh;
  final double batteryDischargeKwh;

  /// Per-inverter PV breakdown, when the controller reports it. Empty → only the
  /// summed PV total ([pvKwh] / [EnergyHistoryPoint.pvW]) is available.
  final List<PvDeviceSeries> pvSeries;

  /// True when the controller reported a per-device PV breakdown — then the
  /// individual inverter lines are drawn (by device name) instead of the summed
  /// "Solar" total. Older firmware reports none → the total line is used.
  bool get hasPvBreakdown => pvSeries.isNotEmpty;
  bool get isEmpty => points.isEmpty;

  /// Peak power across every drawn series — drives the chart's Y scale. When a
  /// PV breakdown exists the individual inverter lines (not the summed total)
  /// are what's drawn, so scale to those.
  double get peakW {
    if (points.isEmpty) return 0;
    var peak = 0.0;
    for (final p in points) {
      final consumptionSide =
          [p.gridImportW, p.gridExportW, p.loadW].reduce((a, b) => a > b ? a : b);
      if (consumptionSide > peak) peak = consumptionSide;
      if (!hasPvBreakdown && p.pvW > peak) peak = p.pvW;
    }
    if (hasPvBreakdown) {
      for (final s in pvSeries) {
        if (s.peakW > peak) peak = s.peakW;
      }
    }
    return peak;
  }

  /// Convert a bucket's **average power (W)** into the **energy (kWh)** it
  /// represents over one bucket's duration — the unit the history chart plots
  /// (kWh per bucket = avg-kW × bucket-hours).
  double kwhFromW(double avgW) => avgW * bucket.inSeconds / 3600000.0;

  /// Consumption energy (kWh) in bucket [i].
  double bucketConsumptionKwh(int i) => kwhFromW(points[i].consumptionW);

  /// Largest single-bucket value (kWh) across every drawn series — drives the
  /// chart's Y scale. Mirrors [peakW] but in per-bucket energy.
  double get peakKwh => kwhFromW(peakW);

  /// Whole-home consumption over the window, from the energy balance:
  ///   consumption = generated + imported + battery discharge
  ///               − exported − battery charge
  /// This is grounded in the grid + PV (+ battery) meters, so it's robust even
  /// when individual loads aren't metered (unlike [loadKwh]). Clamped ≥ 0.
  double get consumptionKwh {
    final c = pvKwh +
        gridImportKwh +
        batteryDischargeKwh -
        gridExportKwh -
        batteryChargeKwh;
    return c > 0 ? c : 0;
  }

  /// Share of consumption met from own generation/storage rather than bought
  /// from the grid, 0–100: `(consumed − imported) / consumed`. Null when there
  /// was no consumption.
  int? get selfSufficiencyPercent {
    final c = consumptionKwh;
    if (c <= 0) return null;
    final selfConsumed = c - gridImportKwh;
    return ((selfConsumed / c).clamp(0.0, 1.0) * 100).round();
  }

  factory EnergyHistoryData.fromProto($proto.EnergyHistory h) {
    final bucketSec = h.bucketSeconds == 0 ? 900 : h.bucketSeconds;
    final start = h.start.toInt(); // epoch seconds of bucket 0
    final perHour = bucketSec / 3600.0; // fraction of an hour per bucket

    // Wh → average W over the bucket.
    double watts(int wh) => wh / perHour;

    final points = <EnergyHistoryPoint>[];
    var pvWh = 0, impWh = 0, expWh = 0, loadWh = 0, batChgWh = 0, batDisWh = 0;
    for (final b in h.buckets) {
      pvWh += b.pvWh;
      impWh += b.gridImportWh;
      expWh += b.gridExportWh;
      loadWh += b.loadWh;
      batChgWh += b.batteryChargeWh;
      batDisWh += b.batteryDischargeWh;
      points.add(EnergyHistoryPoint(
        time: DateTime.fromMillisecondsSinceEpoch(
            (start + b.index * bucketSec) * 1000),
        pvW: watts(b.pvWh),
        gridImportW: watts(b.gridImportWh),
        gridExportW: watts(b.gridExportWh),
        loadW: watts(b.loadWh),
      ));
    }
    // Per-device PV breakdown (index-aligned to buckets), if the controller
    // reported it. Each series' wh[] is dense and aligned to h.buckets by index.
    final pvSeries = <PvDeviceSeries>[];
    for (final s in h.deviceSeries) {
      if (s.cls != $proto.EnergyClass.ENERGY_CLASS_PV) continue;
      var total = 0;
      final watts = <double>[];
      for (var i = 0; i < points.length; i++) {
        final wh = i < s.wh.length ? s.wh[i] : 0;
        total += wh;
        watts.add(wh / perHour);
      }
      pvSeries.add(PvDeviceSeries(
        nodeId: s.nodeId.toInt(),
        name: s.name.isNotEmpty ? s.name : 'PV ${s.nodeId.toInt()}',
        wattsPerBucket: watts,
        kwh: total / 1000.0,
      ));
    }

    return EnergyHistoryData(
      points: points,
      bucket: Duration(seconds: bucketSec),
      timeSynced: h.timeSynced,
      truncated: h.truncated,
      pvKwh: pvWh / 1000.0,
      gridImportKwh: impWh / 1000.0,
      gridExportKwh: expWh / 1000.0,
      loadKwh: loadWh / 1000.0,
      batteryChargeKwh: batChgWh / 1000.0,
      batteryDischargeKwh: batDisWh / 1000.0,
      pvSeries: pvSeries,
    );
  }
}

// ── Value readout (totals, or the scrubbed bucket) ──────────────────────────
Widget _readout(BuildContext context, EnergyHistoryData data) {
  final tt = Theme.of(context).textTheme;
  final cs = Theme.of(context).colorScheme;
  final sel = _selected != null &&
          _selected! >= 0 &&
          _selected! < data.points.length
      ? data.points[_selected!]
      : null;

  if (sel == null) {
    // Default: 12-hour consumption total.
    return Row(
      crossAxisAlignment: CrossAxisAlignment.baseline,
      textBaseline: TextBaseline.alphabetic,
      children: [
        Text(_fmtKwh(data.consumptionKwh), style: tt.headlineMedium?.copyWith(
            fontWeight: FontWeight.w700, color: cs.onSurface)),
        Text(' kWh', style: tt.titleMedium?.copyWith(color: cs.onSurfaceVariant)),
        const SizedBox(width: 8),
        Text('consumed · 12 h',
            style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
      ],
    );
  }

  final idx = _selected!;
  final h = sel.time.hour.toString().padLeft(2, '0');
  final m = sel.time.minute.toString().padLeft(2, '0');
  return Column(
    crossAxisAlignment: CrossAxisAlignment.start,
    children: [
      Text('$h:$m', style: tt.titleMedium?.copyWith(
          fontWeight: FontWeight.w700, color: cs.onSurface)),
      const SizedBox(height: 4),
      Wrap(spacing: 12, runSpacing: 2, children: [
        if (data.hasPvBreakdown)
          for (var k = 0; k < data.pvSeries.length; k++)
            _readoutChip(
                _pvPalette[k % _pvPalette.length],
                _pvName(context, data.pvSeries[k]),
                data.kwhFromW(idx < data.pvSeries[k].wattsPerBucket.length
                    ? data.pvSeries[k].wattsPerBucket[idx]
                    : 0))
        else
          _readoutChip(_pvColor, 'Solar', data.kwhFromW(sel.pvW)),
        _readoutChip(_loadColor, 'Home', data.kwhFromW(sel.loadW)),
        _readoutChip(_importColor, 'Import', data.kwhFromW(sel.gridImportW)),
        _readoutChip(_exportColor, 'Export', data.kwhFromW(sel.gridExportW)),
      ]),
    ],
  );
}

Widget _readoutChip(Color c, String label, double kwh) {
  return Builder(builder: (context) {
    final tt = Theme.of(context).textTheme;
    final cs = Theme.of(context).colorScheme;
    return Row(mainAxisSize: MainAxisSize.min, children: [
      Container(width: 8, height: 8, decoration:
          BoxDecoration(color: c, borderRadius: BorderRadius.circular(2))),
      const SizedBox(width: 4),
      Text('$label ', style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
      Text('${_fmtKwh(kwh)} kWh',
          style: tt.bodySmall?.copyWith(color: cs.onSurface, fontWeight: FontWeight.w600)),
    ]);
  });
}

// ── Chart ───────────────────────────────────────────────────────────────────
Widget _chart(EnergyHistoryData data) {
  return AspectRatio(
    aspectRatio: 1.7,
    child: LayoutBuilder(builder: (context, constraints) {
      final cs = Theme.of(context).colorScheme;
      void selectAt(Offset local) {
        final n = data.points.length;
        if (n < 2) return;
        final frac = (local.dx / constraints.maxWidth).clamp(0.0, 1.0);
        setState(() => _selected = (frac * (n - 1)).round());
      }

      return GestureDetector(
        onHorizontalDragStart: (d) => selectAt(d.localPosition),
        onHorizontalDragUpdate: (d) => selectAt(d.localPosition),
        onHorizontalDragEnd: (_) => setState(() => _selected = null),
        onHorizontalDragCancel: () => setState(() => _selected = null),
        onTapDown: (d) => selectAt(d.localPosition),
        onTapUp: (_) => setState(() => _selected = null),
        child: CustomPaint(
          painter: _LineChartPainter(
            data: data,
            selected: _selected,
            axisColor: cs.onSurfaceVariant.withValues(alpha: 0.30),
            labelColor: cs.onSurfaceVariant,
          ),
        ),
      );
    }),
  );
}

String _pvName(BuildContext context, PvDeviceSeries s) =>
    context.read<DeviceProvider>().deviceNameForNode(s.nodeId) ?? s.name;

// ── Legend ────────────────────────────────────────────────────────────────
Widget _legend(BuildContext context, EnergyHistoryData data) {
  return Wrap(
    spacing: 16, runSpacing: 6, alignment: WrapAlignment.center,
    children: [
      if (data.hasPvBreakdown)
        for (var k = 0; k < data.pvSeries.length; k++)
          _legendItem(context, _pvPalette[k % _pvPalette.length],
              _pvName(context, data.pvSeries[k]))
      else
        _legendItem(context, _pvColor, 'Solar'),
      _legendItem(context, _loadColor, 'Home'),
      _legendItem(context, _importColor, 'Grid import'),
      _legendItem(context, _exportColor, 'Grid export'),
    ],
  );
}

Widget _legendItem(BuildContext context, Color c, String label) {
  final tt = Theme.of(context).textTheme;
  final cs = Theme.of(context).colorScheme;
  return Row(mainAxisSize: MainAxisSize.min, children: [
    Container(width: 14, height: 3, color: c),
    const SizedBox(width: 6),
    Text(label, style: tt.bodySmall?.copyWith(color: cs.onSurfaceVariant)),
  ]);
}

// ── KPI totals ──────────────────────────────────────────────────────────────
Widget _kpis(BuildContext context, EnergyHistoryData data) {
  final ss = data.selfSufficiencyPercent;
  return Column(children: [
    Row(children: [
      _kpi(context, 'Generated', data.pvKwh, _pvColor),
      _kpi(context, 'Consumed', data.consumptionKwh, _loadColor),
    ]),
    const SizedBox(height: 10),
    Row(children: [
      _kpi(context, 'Imported', data.gridImportKwh, _importColor),
      _kpi(context, 'Exported', data.gridExportKwh, _exportColor),
    ]),
    if (ss != null) ...[
      const SizedBox(height: 12),
      _selfSufficiency(context, ss),
    ],
  ]);
}

Widget _kpi(BuildContext context, String label, double kwh, Color c) {
  final tt = Theme.of(context).textTheme;
  final cs = Theme.of(context).colorScheme;
  return Expanded(
    child: Row(children: [
      Container(width: 3, height: 30, decoration:
          BoxDecoration(color: c, borderRadius: BorderRadius.circular(2))),
      const SizedBox(width: 10),
      Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Text(label.toUpperCase(), style: tt.labelSmall?.copyWith(
            color: cs.onSurfaceVariant, letterSpacing: 0.8)),
        const SizedBox(height: 2),
        Text('${_fmtKwh(kwh)} kWh',
            style: tt.titleMedium?.copyWith(
                color: cs.onSurface, fontWeight: FontWeight.w700)),
      ]),
    ]),
  );
}

Widget _selfSufficiency(BuildContext context, int pct) {
  final tt = Theme.of(context).textTheme;
  final cs = Theme.of(context).colorScheme;
  return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
    Row(children: [
      Text('SELF-SUFFICIENCY', style: tt.labelSmall?.copyWith(
          color: cs.onSurfaceVariant, letterSpacing: 0.8)),
      const Spacer(),
      Text('$pct%', style: tt.labelMedium?.copyWith(
          color: cs.onSurface, fontWeight: FontWeight.w700)),
    ]),
    const SizedBox(height: 6),
    ClipRRect(
      borderRadius: BorderRadius.circular(3),
      child: LinearProgressIndicator(
        value: pct / 100,
        minHeight: 6,
        backgroundColor: cs.surfaceContainerHighest,
        valueColor: const AlwaysStoppedAnimation(_exportColor),
      ),
    ),
  ]);
}

// ── Placeholder / footnote ──────────────────────────────────────────────────
Widget _placeholder(BuildContext context, bool loading, {bool empty = false}) {

content.text:
Yes, I understand it — and it's a real artifact, not a data problem. Here's exactly what's happening and where.

## The problem

The chart's newest point is the **in-progress hour**. The controller's `aggregate()` emits a bucket for the current hour that only contains the Wh accrued *so far* (e.g. 15 min into the hour). But the app converts every bucket's Wh to an average power by dividing by a **full** hour:

```dart
// energy_history.dart:159-162
final perHour = bucketSec / 3600.0;   // = 1.0 for 1-hour buckets
double watts(int wh) => wh / perHour; // divides partial energy by a FULL hour
```

So at 15 min past the hour, the last point shows ~¼ of the true current power (and as a kWh-per-hour bar it's genuinely only ¼-full), then climbs as the hour fills. Result: the rightmost point always dips low and creeps up. The KPI totals (Generated/Consumed) are fine — they sum real Wh — it's only the per-bucket chart tail that's misleading.

## Recommended fix — normalize the current bucket by *elapsed* time

Since the series is semantically "average power over the bucket," divide the final (partial) bucket's Wh by the **elapsed** seconds, not the nominal bucket length. Then the last point reflects the current average rate and stops dipping. In `EnergyHistoryData.fromProto`:

```dart
factory EnergyHistoryData.fromProto($proto.EnergyHistory h, {DateTime? asOf}) {
  ...
  final perHour = bucketSec / 3600.0;

  // The final bucket is mid-interval; scale it by how much has actually elapsed
  // so it reads as current power, not a value diluted by the rest of the hour.
  var lastPerHour = perHour;
  if (h.timeSynced && h.buckets.isNotEmpty) {
    final lastStart = start + h.buckets.last.index * bucketSec;
    final nowSec = (asOf ?? DateTime.now()).millisecondsSinceEpoch ~/ 1000;
    final elapsed = nowSec - lastStart;
    if (elapsed >= 300 && elapsed < bucketSec) lastPerHour = elapsed / 3600.0; // 5-min floor
  }

  double wattsFor(int wh, bool isLast) => wh / (isLast ? lastPerHour : perHour);
  // use wattsFor(..., i == h.buckets.length - 1) for both the summed points
  // and each pvSeries entry
}
```

Guards that matter:
- **`timeSynced` only** — the elapsed calc relies on the phone clock lining up with the controller's bucket start; skip it if the controller clock isn't synced.
- **5-min floor** — early in the hour, dividing a tiny Wh by a tiny time is noisy and would spike the Y-axis (`peakW`); leave it un-normalized (or hide it) until enough has elapsed.
- Note this makes the last point a *rate*, so a scrubbed readout of that bucket becomes "projected kWh for the hour" — decide whether you want the readout to say "so far" instead.

## Alternatives (trade-offs)

- **Drop the in-progress bucket** — simplest and most honest if you treat the chart as energy/kWh; the chart always ends on a complete hour. Cost: up to 1 h of latency, no live tail.
- **Mark it in-progress** — draw the last segment dashed/faded and label it "so far this hour." Keeps the raw accumulating value but signals it's incomplete so it isn't misread as a drop. Pairs well with excluding it from `peakW`.
- **Fix it controller-side** (cleanest long-term) — have `aggregate()` either omit the trailing partial bucket or emit its elapsed seconds in the proto, so the app normalizes with the *authoritative* clock instead of guessing with the phone's. Avoids the clock-skew caveat entirely, at the cost of a firmware + proto change.

My pick: the app-side elapsed-normalization (no firmware needed) **plus** visually marking the tail as in-progress. If you'd rather be conservative, dropping the partial bucket is the one-liner.

Want me to implement the normalization approach in `energy_history.dart` (threading `asOf` through `fetchEnergyHistory` for testability)?

