      ));
      expect(selfSufficient.consumptionKwh, closeTo(0.4, 0.0001));
      expect(selfSufficient.selfSufficiencyPercent, 100);

      // All consumption from the grid (no generation) → 0%.
      final fromGrid = EnergyHistoryData.fromProto($proto.EnergyHistory(
        bucketSeconds: 900,
        buckets: [$proto.EnergyBucket(index: 0, gridImportWh: 400)],
      ));
      expect(fromGrid.consumptionKwh, closeTo(0.4, 0.0001));
      expect(fromGrid.selfSufficiencyPercent, 0);
    });

    test('consumption + self-sufficiency use the energy balance', () {
      // Generated 1000, exported 600, imported 200, battery charge 100:
      //   consumption = 1000 + 200 + 0 − 600 − 100 = 500 Wh
      //   self-consumed = 500 − 200 = 300 → 60%.
      final d = EnergyHistoryData.fromProto($proto.EnergyHistory(
        bucketSeconds: 900,
        buckets: [
          $proto.EnergyBucket(
            index: 0,
            pvWh: 1000,
            gridExportWh: 600,
            gridImportWh: 200,
            batteryChargeWh: 100,
          ),
        ],
      ));
      expect(d.consumptionKwh, closeTo(0.5, 0.0001));
      expect(d.selfSufficiencyPercent, 60);
    });

    test('per-PV device series decode: aligned watts, totals, and names', () {
      final h = $proto.EnergyHistory(
        start: Int64(1_000_000),
        bucketSeconds: 900,
        buckets: [
          $proto.EnergyBucket(index: 0, pvWh: 500),
          $proto.EnergyBucket(index: 1, pvWh: 250),
        ],
        deviceSeries: [
          $proto.EnergyDeviceSeries(
            nodeId: Int64(0x0100000000000002),
            cls: $proto.EnergyClass.ENERGY_CLASS_PV,
            name: 'Roof East',
            wh: [250, 250], // 250 Wh/bucket = 1000 W avg
          ),
          $proto.EnergyDeviceSeries(
            nodeId: Int64(0x0100000000000003),
            cls: $proto.EnergyClass.ENERGY_CLASS_PV,
            name: 'Roof West',
            wh: [250, 0],
          ),
        ],
      );

      final d = EnergyHistoryData.fromProto(h);
      expect(d.hasPvBreakdown, isTrue);
      expect(d.pvSeries.map((s) => s.name), ['Roof East', 'Roof West']);
      expect(d.pvSeries[0].wattsPerBucket, [closeTo(1000, 0.001), closeTo(1000, 0.001)]);
      expect(d.pvSeries[1].wattsPerBucket, [closeTo(1000, 0.001), 0]);
      expect(d.pvSeries[0].kwh, closeTo(0.5, 0.0001));
      expect(d.pvSeries[1].kwh, closeTo(0.25, 0.0001));
      // Per-device series sum matches the summed PV total.
      expect(d.pvSeries.fold<double>(0, (a, s) => a + s.kwh),
          closeTo(d.pvKwh, 0.0001));
    });

    test('no device_series → no breakdown (older firmware)', () {
      final d = EnergyHistoryData.fromProto($proto.EnergyHistory(
        bucketSeconds: 900,
        buckets: [$proto.EnergyBucket(index: 0, pvWh: 100)],
      ));
      expect(d.hasPvBreakdown, isFalse);
      expect(d.pvSeries, isEmpty);
    });

    test('no consumption → null self-sufficiency, empty history is empty', () {
      // Everything generated was exported → zero net consumption → null.
      final none = EnergyHistoryData.fromProto($proto.EnergyHistory(
        bucketSeconds: 900,
        buckets: [$proto.EnergyBucket(index: 0, pvWh: 100, gridExportWh: 100)],
      ));
      expect(none.consumptionKwh, 0);
      expect(none.selfSufficiencyPercent, isNull);

      final empty = EnergyHistoryData.fromProto($proto.EnergyHistory());
      expect(empty.isEmpty, isTrue);
      expect(empty.peakW, 0);
    });

    test('drops the in-progress bucket (the one containing `to`)', () {
      // 1-hour buckets; `to` falls 2 h 30 m in → bucket index 2 is still filling
      // and must be excluded from both the chart and the totals.
      final h = $proto.EnergyHistory(
        bucketSeconds: 3600, // start defaults to 0
        to: Int64(9000), // inside bucket index 2
        timeSynced: true,
        buckets: [
          $proto.EnergyBucket(index: 0, pvWh: 1000),
          $proto.EnergyBucket(index: 1, pvWh: 1000),
          $proto.EnergyBucket(index: 2, pvWh: 100), // partial → dropped
        ],
        deviceSeries: [
          $proto.EnergyDeviceSeries(
            nodeId: Int64(0x0100000000000002),
            cls: $proto.EnergyClass.ENERGY_CLASS_PV,
            name: 'Roof',
            wh: [1000, 1000, 100],
          ),
        ],
      );

      final d = EnergyHistoryData.fromProto(h);

      expect(d.points.length, 2); // only the two complete hours
      expect(d.pvKwh, closeTo(2.0, 0.0001)); // 2000 Wh, not 2100
      expect(d.pvSeries.single.wattsPerBucket.length, 2);
      expect(d.pvSeries.single.kwh, closeTo(2.0, 0.0001));
    });

    test('`to` on a bucket boundary keeps all complete buckets', () {
      // `to` exactly at 2 h → the bucket that would start there is empty/future;
      // the two complete hours before it are kept.
      final d = EnergyHistoryData.fromProto($proto.EnergyHistory(
        start: Int64(0),
        bucketSeconds: 3600,
        to: Int64(7200),
        buckets: [
          $proto.EnergyBucket(index: 0, pvWh: 500),
          $proto.EnergyBucket(index: 1, pvWh: 500),
        ],
      ));
      expect(d.points.length, 2);
      expect(d.pvKwh, closeTo(1.0, 0.0001));
    });
  });
}

content.text:
Done. All tests pass and no new lints — the 5 remaining are pre-existing (the untouched `factory`-ordering and multi-var lines in `energy_history.dart`) or match the existing test file's `Int64(0x…)` hex style.

## What changed

In `lib/models/energy_history.dart`, `EnergyHistoryData.fromProto` now drops the in-progress bucket before building anything:

```dart
// The bucket containing the query's end time is still in progress: it holds
// only the energy accrued so far this interval, so it always reads low and
// climbs as the interval fills. Drop it (and anything at/after it) ...
final to = h.to.toInt();
final inProgressIndex = to > start ? (to - start) ~/ bucketSec : 1 << 30;
final buckets = [
  for (final b in h.buckets)
    if (b.index < inProgressIndex) b,
];
```

Key points:
- **Identified via the controller's own `to`/`start`/`bucketSeconds`**, so it uses the controller's clock — no phone-wall-clock skew, and the whole change is app-side (no firmware needed).
- **Chart *and* totals stay consistent** — everything downstream (points, KPI totals, per-PV device series) is derived from the filtered list, so `sum(pvSeries.kwh) == pvKwh` still holds. The chart now ends on the last *complete* hour instead of a diving partial one.
- **Boundary-safe**: when `to` lands exactly on a bucket boundary, the empty/future bucket is excluded and the complete hours are kept.
- **Backward-compatible**: the `to > start` guard means older/`to`-unset responses (and all existing tests) get no cutoff.

Two tests added: one asserting the partial trailing bucket is excluded from chart and totals, one for the exact-boundary case.

Trade-off to be aware of: the "consumed · 12 h" headline and KPIs now exclude the current partial hour, so they read as "complete hours only" — slightly more conservative, but consistent with the chart and no longer misleading.

This is unit-tested but not yet running on a device (the installed app is the older release). Want me to `flutter build apk --release` and reinstall on the Pixel (and the Nothing Phone) so you can see it live?
